contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint amount, address proposedAddress, string memory typeStr) public payable {
        require(bytes(typeStr).length > 0);

        uint beforeGrantCount = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint afterGrantCount = c.proposalCount();
        uint grantId = afterGrantCount;

        uint beforeAddrCount = c.proposalCount();
        c.newAddressProposal(proposedAddress, typeStr);
        uint afterAddrCount = c.proposalCount();
        uint addrId = afterAddrCount;

        (address storedRecipient, uint storedAmount) = c.mapPID_grant(grantId);
        address storedProposedAddress = c.mapPID_address(addrId);

        assert(
            afterGrantCount == beforeGrantCount + 1 &&
            bytes(c.mapPID_type(grantId)).length > 0 &&
            storedRecipient == recipient &&
            storedAmount == amount &&
            afterAddrCount == beforeAddrCount + 1 &&
            bytes(c.mapPID_type(addrId)).length > 0 &&
            storedProposedAddress == proposedAddress
        );
    }
}

