contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint nonce, address recipient, uint amount) public {
        require(recipient != address(0), "zero recipient");
        require(nonce > 0, "nonce must be positive");

        c.init(address(this), address(this), address(this));

        c.newGrantProposal(recipient, amount);

        uint proposalId = c.proposalCount();
        uint timeBeforeFinalise = block.timestamp;

        c.voteProposal(proposalId);

        uint timeStart = c.mapPID_timeStart(proposalId);
        bool isFinalising = c.mapPID_finalising(proposalId);

        bool reverted;
        try c.finaliseProposal(proposalId) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool finalised = c.mapPID_finalised(proposalId);

        assert(finalised == false || (isFinalising && block.timestamp <= timeBeforeFinalise + c.coolOffPeriod()));
    }
}

